import{_ as i,W as n,o as l,c as d,aa as s,a as e,E as a,Y as o}from"./chunks/framework.Pz9vw46u.js";import"./chunks/theme.Bqo48-vV.js";const x=JSON.parse(`{"title":"Flyweight Pattern","description":"20,000,000 live formula-capable cells in 89 MB — 4.7 bytes each — created in 67 ms, with memory that never grows past the viewport. Observation-priced existence, ivue's invariant taken all the way down.","frontmatter":{"title":"Flyweight Pattern","description":"20,000,000 live formula-capable cells in 89 MB — 4.7 bytes each — created in 67 ms, with memory that never grows past the viewport. Observation-priced existence, ivue's invariant taken all the way down."},"headers":[],"relativePath":"guide/flyweight.md","filePath":"guide/flyweight.md","lastUpdated":1786381307000}`),h={name:"guide/flyweight.md"},c={class:"benchmark-legend"},p={tabindex:"0"},u={style:{"text-align":"right"}};function g(m,t,f,v,b,y){const r=n("BenchmarkWinner");return l(),d("div",null,[t[8]||(t[8]=s('<h1 id="flyweight-pattern-—-observation-priced-existence" tabindex="-1">Flyweight Pattern — observation-priced existence <a class="header-anchor" href="#flyweight-pattern-—-observation-priced-existence" aria-label="Permalink to &quot;Flyweight Pattern — observation-priced existence&quot;">​</a></h1><p>Everything in ivue descends from one invariant:</p><blockquote><p><strong>Everything costs proportional to what&#39;s observed; nothing costs proportional to what exists.</strong></p></blockquote><p>Lazy ref-getters apply it to <em>reactive cells</em>: an instance&#39;s refs don&#39;t exist until read. The flyweight pattern applies it one level deeper: <strong>the model objects themselves don&#39;t exist until observed.</strong> Ground truth lives in columnar typed storage; entity objects are disposable facades created per render; reactivity is a sparse overlay that materializes per observation — and is <em>evicted</em> when observation moves away.</p><p>The proof is a working spreadsheet — the <a href="/examples/flyweight-grid">live Flyweight Grid example</a> — <strong>20 columns × 1,000,000 rows = 20,000,000 live cells</strong>, ~55% real Excel-syntax formulas evaluated by <code>fast-formula-parser</code> with Vue-discovered dependencies. A document <em>twice Google Sheets&#39; 10M-cell hard cap</em>.</p><h2 id="the-measured-numbers" tabindex="-1">The measured numbers <a class="header-anchor" href="#the-measured-numbers" aria-label="Permalink to &quot;The measured numbers&quot;">​</a></h2><p>Headless-Chromium heap protocol, gc-forced, 3 runs, medians — deltas bit-identical across runs (full receipts in the sketch&#39;s <code>RESULTS.md</code>):</p><table tabindex="0"><thead><tr><th>Metric</th><th style="text-align:right;">production build</th></tr></thead><tbody><tr><td>Model creation (20,000,000 cells)</td><td style="text-align:right;"><strong>67.1 ms</strong></td></tr><tr><td>Model heap</td><td style="text-align:right;"><strong>89.48 MB</strong></td></tr><tr><td><strong>Bytes per cell</strong></td><td style="text-align:right;"><strong>4.69 B</strong></td></tr><tr><td>After 30 viewports across 1M rows</td><td style="text-align:right;"><strong>+0.3 MB</strong></td></tr></tbody></table><p>The per-cell cost ladder, all arms measured with the same protocol:</p>',9)),e("p",c,[t[0]||(t[0]=a("Best measured result among fully reactive implementations. The POJO control marks the non-reactive floor. ",-1)),o(r,{placement:"after"})]),e("table",p,[t[7]||(t[7]=e("thead",null,[e("tr",null,[e("th",null,"Arm"),e("th",{style:{"text-align":"right"}},"bytes/cell"),e("th",null,"what a cell IS at rest")])],-1)),e("tbody",null,[t[4]||(t[4]=e("tr",null,[e("td",null,"Composable (idiomatic Vue)"),e("td",{style:{"text-align":"right"}},"~758"),e("td",null,"closures + eager ref/computeds")],-1)),t[5]||(t[5]=e("tr",null,[e("td",null,"ivue instance grid"),e("td",{style:{"text-align":"right"}},"~67"),e("td",null,"object + lazy overlay")],-1)),t[6]||(t[6]=e("tr",null,[e("td",null,"Plain POJO floor (no reactivity)"),e("td",{style:{"text-align":"right"}},"~40"),e("td",null,[e("code",null,"{ row, col, raw }")])],-1)),e("tr",null,[t[2]||(t[2]=e("td",null,[e("strong",null,"Flyweight columnar")],-1)),e("td",u,[e("strong",null,[o(r),t[1]||(t[1]=a("4.7",-1))])]),t[3]||(t[3]=e("td",null,"1 B kind + 8 B number ÷ shared",-1))])])]),t[9]||(t[9]=s(`<p><strong>8.5× below the &quot;theoretical floor&quot;</strong> — because the floor was never plain objects; it was ground truth. And still fully reactive, formula-capable, and editable the moment anything observes it.</p><h2 id="the-three-moves" tabindex="-1">The three moves <a class="header-anchor" href="#the-three-moves" aria-label="Permalink to &quot;The three moves&quot;">​</a></h2><p><strong>1. Columnar ground truth.</strong> Per column: a <code>Uint8Array</code> of cell kinds, a lazily-allocated <code>Float64Array</code> for numerics, a sparse <code>Map</code> for text and edited formula sources (default sources are per-column <em>pattern functions</em> — 11M formulas stored as 11 closures). Writes to unobserved cells update the arrays and notify no one — <strong>a value arriving costs nothing until someone looks at it.</strong></p><p><strong>2. Flyweight facades.</strong> The entity class holds three fields — <code>(sheet, row, col)</code> — plus plain getters delegating to the sheet. ivue makes the reactive portion zero-allocation at rest: no getter runs at construction, plain getters de-optimize to native prototype getters, and reads are tracked through whatever effect performs them. Create per render, drop on scroll, zero loss — the reactive state lives on the sheet&#39;s overlay, not on the facade.</p><p><strong>3. A two-tier sparse overlay</strong> (the <a href="/guide/state#keyed-reactivity-the-third-shape">keyed-reactivity shape</a>). Fine per-cell version refs for point observers (rendered cells, single-cell formula references — conditional dependencies still shift with the executed branch); coarse per-4,096-row <em>block</em> refs for large ranges — <code>=SUM(A1:A1000000)</code> costs <strong>245 edges, not a million</strong>. A derived-write bridge (each cached formula computed bumps its own block on value change) lets coarse subscribers see through formulas to out-of-range inputs. Viewport-tied <em>eviction</em> releases overlay entries as the window moves: memory is <strong>O(viewport), not O(rows-ever-visited)</strong> — under sustained scrolling the process breathes around a flat floor instead of climbing.</p><h2 id="what-fell-out-measured-not-projected" tabindex="-1">What fell out (measured, not projected) <a class="header-anchor" href="#what-fell-out-measured-not-projected" aria-label="Permalink to &quot;What fell out (measured, not projected)&quot;">​</a></h2><ul><li><strong>Bulk aggregation belongs to the columnar layer.</strong> The stock parser&#39;s range aggregation measured O(n²) — 27 ms at 10k cells, 40 s at 200k. A linear columnar fast path for bare <code>SUM/AVERAGE/MIN/MAX/COUNT(range)</code> (same observation semantics) closed a five-orders-of-magnitude gap — the same reason desktop engines special-case range ops.</li><li><strong>The development model stays honest.</strong> The 20M-cell example runs the same ivue construction and method-binding path in development and production. Script edits rebuild their owner through Vue instead of mixing one live model generation with another.</li><li><strong>The scroll walls are physical.</strong> Chrome&#39;s compositor does scroll math in float32 (dead past 2^24 px ≈ row 599,186 of a 28px-row grid); Firefox caps element height at ~17.9M px. The scaled scrollbar (capped physical height, ratio-mapped virtual offset) clears both.</li></ul><h2 id="where-the-pattern-fits" tabindex="-1">Where the pattern fits <a class="header-anchor" href="#where-the-pattern-fits" aria-label="Permalink to &quot;Where the pattern fits&quot;">​</a></h2><p>Anywhere <strong>data grows faster than attention</strong>: AI token-stream/trace viewers (a token arriving costs nothing until observed), log tails with live windowed aggregates, dataframe viewers (Arrow columns <em>are</em> typed arrays — zero-copy adoption), time-series dashboards, collaborative grids (remote edits to unobserved cells are peek-only writes). Observation-priced reactivity turns &quot;it slows down as it fills up&quot; into a flat line.</p><h2 id="honest-boundaries" tabindex="-1">Honest boundaries <a class="header-anchor" href="#honest-boundaries" aria-label="Permalink to &quot;Honest boundaries&quot;">​</a></h2><p>Eviction uses a dependency-locality margin (production wants refcounts); compound formulas over giant ranges inherit the general parser&#39;s cost; the Sheets comparison is architectural (a 20M-cell document exceeds its cap), not benchmarked. Run it yourself:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> dev:flyweight</span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">       # the demo, with a live observation census</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> measure:flyweight</span><span style="--shiki-light:#6A737D;--shiki-light-font-style:inherit;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # the heap protocol (pass the URL)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,12))])}const T=i(h,[["render",g]]);export{x as __pageData,T as default};
